SELECT COUNT(*) FROM enrollment e JOIN course c ON e.course_id = c.id LEFT JOIN student s ON e.student_id = s.id LEFT JOIN users u ON s.user_id = u.id LEFT JOIN subject sj ON c.subject_id = sj.id LEFT JOIN grade g ON e.id = g.enrollment_id WHERE c.professor_id = #{professorId} AND c.id = #{courseId} AND sj.id = #{subjectId}
AND (
u.name LIKE '%' || #{searchKeyword} || '%' s.student_num LIKE '%' || #{searchKeyword} || '%' sj.name LIKE '%' || #{searchKeyword} || '%' g.alphabet LIKE '%' || #{searchKeyword} || '%'
)

SELECT * FROM ( SELECT t.*, ROWNUM rn FROM ( SELECT g.id, g.alphabet, g.gpa AS GPA, g.score, g.total_int, g.mid_exam, g.final_exam, g.assignment, g.attendance, e.student_id, e.id as ENROLLMENT_ID, sj.name AS subjectName, s.student_num AS studentNo, u.name AS studentName FROM enrollment e JOIN course c ON e.course_id = c.id LEFT JOIN student s ON e.student_id = s.id LEFT JOIN users u ON s.user_id = u.id LEFT JOIN subject sj ON c.subject_id = sj.id LEFT JOIN grade g ON e.id = g.enrollment_id WHERE c.professor_id = #{professorId} AND c.id = #{courseId} AND sj.id = #{subjectId}
AND (
u.name LIKE '%' || #{searchKeyword} || '%' s.student_num LIKE '%' || #{searchKeyword} || '%' sj.name LIKE '%' || #{searchKeyword} || '%' g.alphabet LIKE '%' || #{searchKeyword} || '%'
)
ORDER BY g.id DESC ) t WHERE ROWNUM <= #{end} ) WHERE rn > #{start}

