mapper.select:
SELECT * FROM ( SELECT t.*, ROWNUM rn FROM ( SELECT g.id, g.alphabet, g.gpa AS GPA, g.score, g.total_int, g.mid_exam, g.final_exam, g.assignment, g.attendance, g.student_id, g.enrollment_id, sj.name AS subjectName, s.student_num AS studentNo, u.name AS studentName FROM grade g JOIN enrollment e ON g.enrollment_id = e.id JOIN course c ON e.course_id = c.id LEFT JOIN subject sj ON c.subject_id = sj.id LEFT JOIN student s ON g.student_id = s.id LEFT JOIN users u ON s.user_id = u.id WHERE g.student_id = #{studentId}
AND ( TO_CHAR(g.id) LIKE '%' || #{searchKeyword} || '%' OR UPPER(sj.name) LIKE '%' || UPPER(#{searchKeyword}) || '%' OR UPPER(g.alphabet) LIKE '%' || UPPER(#{searchKeyword}) || '%' )
AND g.id = TO_NUMBER(#{searchKeyword})
AND UPPER(sj.name) LIKE '%' || UPPER(#{searchKeyword}) || '%'
AND UPPER(g.alphabet) LIKE '%' || UPPER(#{searchKeyword}) || '%'
ORDER BY g.id DESC ) t WHERE ROWNUM <= #{end} ) WHERE rn > #{start}

SELECT course_id
FROM enrollment
WHERE id = #{enrollmentId}

SELECT COUNT(*)
FROM grade g
         JOIN enrollment e ON g.enrollment_id = e.id
         JOIN course c     ON e.course_id     = c.id
WHERE g.id = #{gradeId}
  AND c.professor_id = #{professorId}

SELECT * FROM ( SELECT courseId, courseName, subjectId, subjectName, credit, semesterId, semesterName, semesterYear, enrollmentCount, ROW_NUMBER() OVER (ORDER BY courseId DESC) as rn FROM ( SELECT c.id as courseId, s.name as courseName, s.id as subjectId, s.name as subjectName, s.credit, se.id as semesterId, se.name as semesterName, se.year as semesterYear, COUNT(e.id) as enrollmentCount FROM course c JOIN subject s ON c.subject_id = s.id JOIN semester se ON c.semester_id = se.id LEFT JOIN enrollment e ON c.id = e.course_id WHERE c.professor_id = #{professorId}
AND s.name LIKE '%' || #{searchKeyword} || '%'
AND s.name LIKE '%' || #{searchKeyword} || '%'
GROUP BY c.id, s.id, s.name, s.credit, se.id, se.name, se.year ) ) WHERE rn BETWEEN #{start} AND #{end}

SELECT COUNT(DISTINCT c.id) FROM course c JOIN subject s ON c.subject_id = s.id WHERE c.professor_id = #{professorId}
AND s.name LIKE '%' || #{searchKeyword} || '%'
AND s.name LIKE '%' || #{searchKeyword} || '%'

SELECT * FROM ( SELECT s.id as subjectId, s.name as subjectName, s.credit, ROW_NUMBER() OVER (ORDER BY s.id DESC) as rn FROM subject s
AND UPPER(s.name) LIKE '%' || UPPER(#{searchKeyword}) || '%'
AND s.id = TO_NUMBER(#{searchKeyword})
AND (UPPER(s.name) LIKE '%' || UPPER(#{searchKeyword}) || '%' OR s.id = TO_NUMBER(#{searchKeyword}))
) WHERE rn BETWEEN #{start} AND #{end}
